const stamp = toIsoTimestamp(new Date());
const current = getDb()
  .select()
  .from(issues)
  .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
  .get();

if (!current) throw new Error(`Issue ${issueId} not found`);

const closing = TERMINAL_STATUSES.includes(status);
const wasClosed = TERMINAL_STATUSES.includes(current.status);
// Entering a closed status stamps a new completion time. Leaving one
// clears it. Moving between done and canceled keeps the original stamp.
// startedAt stays the first time the issue entered in progress.
const completedAt = closing
  ? wasClosed && current.completedAt !== null
    ? current.completedAt
    : stamp
  : null;

const row = getDb()
  .update(issues)
  .set({
    status,
    startedAt:
      status === "in_progress" && current.startedAt === null
        ? stamp
        : current.startedAt,
    completedAt,
    updatedAt: stamp,
  })

const closedStatuses = [...CLOSED_ISSUE_STATUSES];

const closed = db
  .select({ value: count() })
  .from(issues)
  .where(and(scope, inArray(issues.status, closedStatuses)))
  .get();

const all = db.select({ value: count() }).from(issues).where(scope).get();

const overdue = db
  .select({ value: count() })
