/** Every workspace that has not been deleted. Deleted orgs stay archived. */
export async function listLiveOrgIds(): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ id: organizations.id })
    .from(organizations)
    .where(and(...compact(livePredicate(organizations.archivedAt, {}))))
    .all();

