/** Open, live issues whose due time is strictly before this sweep. */
function isSweepOverdue(issue: Issue, now: Date): boolean {
  if (isArchived(issue)) return false;
  if (CLOSED_ISSUE_STATUSES.includes(issue.status)) return false;
  return isOverdue(issue.dueAt, now);
}

