export async function setIssueStatus(
  orgId: OrgId,
  issueId: IssueId,
  status: IssueStatus,
): Promise<Issue> {
  const stamp = toIsoTimestamp(new Date());
  const current = getDb()
    .select()
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .get();

  if (!current) throw new Error(`Issue ${issueId} not found`);

  const closing = TERMINAL_STATUSES.includes(status);
  const wasClosed = TERMINAL_STATUSES.includes(current.status);
  // Entering a closed status stamps a new completion time. Leaving one
  // clears it. Moving between done and canceled keeps the original stamp.
  // startedAt stays the first time the issue entered in progress.
  const completedAt = closing
